import React, { useState, useEffect, useMemo } from 'react';
import {
    Box, Typography, Container, Grid, Card, CardContent,
    TextField, Button, Chip, CircularProgress, Divider,
    MenuItem, Select, FormControl, InputLabel, Paper,
    InputAdornment, CardActions, Breadcrumbs, Link, IconButton,
    useTheme, Pagination, Alert
} from '@mui/material';
import { Link as RouterLink } from 'react-router-dom';
import { useMosqueContext } from '../contexts/MosqueContext';
import { listDirectory, listMasjids } from '../services/masjidService';
import HomeIcon from '@mui/icons-material/Home';
import MosqueIcon from '@mui/icons-material/Mosque';
import SearchIcon from '@mui/icons-material/Search';
import LocationOnIcon from '@mui/icons-material/LocationOn';
import FavoriteIcon from '@mui/icons-material/Favorite';
import FavoriteBorderIcon from '@mui/icons-material/FavoriteBorder';
import DirectionsIcon from '@mui/icons-material/Directions';
import VerifiedIcon from '@mui/icons-material/Verified';
import MyLocationIcon from '@mui/icons-material/MyLocation';
import AddLocationAltIcon from '@mui/icons-material/AddLocationAlt';
import KaabaAnimation from '../components/animations/KaabaAnimation';

const ITEMS_PER_PAGE = 12;
const REGION_NAMES = {
    us: { AL: 'Alabama', AK: 'Alaska', AZ: 'Arizona', AR: 'Arkansas', CA: 'California', CO: 'Colorado', CT: 'Connecticut', DE: 'Delaware', DC: 'District of Columbia', FL: 'Florida', GA: 'Georgia', HI: 'Hawaii', ID: 'Idaho', IL: 'Illinois', IN: 'Indiana', IA: 'Iowa', KS: 'Kansas', KY: 'Kentucky', LA: 'Louisiana', ME: 'Maine', MD: 'Maryland', MA: 'Massachusetts', MI: 'Michigan', MN: 'Minnesota', MS: 'Mississippi', MO: 'Missouri', MT: 'Montana', NE: 'Nebraska', NV: 'Nevada', NH: 'New Hampshire', NJ: 'New Jersey', NM: 'New Mexico', NY: 'New York', NC: 'North Carolina', ND: 'North Dakota', OH: 'Ohio', OK: 'Oklahoma', OR: 'Oregon', PA: 'Pennsylvania', RI: 'Rhode Island', SC: 'South Carolina', SD: 'South Dakota', TN: 'Tennessee', TX: 'Texas', UT: 'Utah', VT: 'Vermont', VA: 'Virginia', WA: 'Washington', WV: 'West Virginia', WI: 'Wisconsin', WY: 'Wyoming', PR: 'Puerto Rico' },
    ca: { AB: 'Alberta', BC: 'British Columbia', MB: 'Manitoba', NB: 'New Brunswick', NL: 'Newfoundland and Labrador', NS: 'Nova Scotia', NT: 'Northwest Territories', NU: 'Nunavut', ON: 'Ontario', PE: 'Prince Edward Island', QC: 'Quebec', SK: 'Saskatchewan', YT: 'Yukon' },
};
const regionLabel = (c, r) => REGION_NAMES[c]?.[r] || r;

// Miles, haversine.
const distanceMi = (a, b) => {
    const rad = (d) => (d * Math.PI) / 180;
    const h = Math.sin(rad(b.la - a.la) / 2) ** 2 + Math.cos(rad(a.la)) * Math.cos(rad(b.la)) * Math.sin(rad(b.lo - a.lo) / 2) ** 2;
    return 3958.8 * 2 * Math.asin(Math.sqrt(h));
};
const favKey = (m) => m.v || m.u;

const AddMasjidCard = () => (
    <Paper elevation={0} variant="outlined" sx={{ p: 3, borderRadius: 2, mt: 4, display: 'flex', gap: 2, alignItems: 'flex-start', flexWrap: 'wrap' }}>
        <AddLocationAltIcon color="primary" sx={{ fontSize: 40 }} />
        <Box sx={{ flex: '1 1 300px' }}>
            <Typography variant="h6" gutterBottom>Is your masjid missing or out of date?</Typography>
            <Typography variant="body2" color="text.secondary">
                Masjids on Masjid Connect keep their own iqamah and Jumu&rsquo;ah times, announcements and Alexa reminders
                up to date here, for free. The rest of the list comes from OpenStreetMap, the free world map anyone can edit.
            </Typography>
        </Box>
        <Box sx={{ display: 'flex', gap: 1, alignSelf: 'center', flexWrap: 'wrap' }}>
            <Button variant="contained" component={RouterLink} to="/masjid-request?kind=add">Add a masjid</Button>
            <Button variant="outlined" component={RouterLink} to="/masjid-request?kind=claim">I run a masjid</Button>
        </Box>
    </Paper>
);

// Static masjid pages are outside the React app: a normal link. Masjid Connect pages are routes.
const MasjidLink = ({ m, children, ...props }) => (m.u.startsWith('/mosque/')
    ? <Link component={RouterLink} to={m.u} {...props}>{children}</Link>
    : <Link href={m.u} {...props}>{children}</Link>);

const MosqueDirectoryPage = () => {
    const theme = useTheme();
    const { favorites, toggleFavorite } = useMosqueContext();

    const [masjids, setMasjids] = useState([]);
    const [isLoading, setIsLoading] = useState(true);
    const [apiError, setApiError] = useState(null);
    const [searchTerm, setSearchTerm] = useState('');
    const [region, setRegion] = useState('all');
    const [filterOption, setFilterOption] = useState('all');
    const [currentPage, setCurrentPage] = useState(1);
    const [here, setHere] = useState(null);
    const [locating, setLocating] = useState(false);
    const [locationError, setLocationError] = useState(null);

    useEffect(() => {
        let cancelled = false;
        Promise.allSettled([listDirectory(), listMasjids()]).then(([index, connect]) => {
            if (cancelled) return;
            const list = index.status === 'fulfilled' ? index.value : [];
            // Masjid Connect masjids added since the nightly index: listed by their live page.
            if (connect.status === 'fulfilled') {
                const known = new Set(list.filter((m) => m.v).map((m) => m.v));
                for (const m of connect.value) {
                    if (known.has(m.id)) continue;
                    list.push({ n: m.name, u: `/mosque/${encodeURIComponent(m.id)}`, t: m.city || null, r: null, c: null, v: m.id, address: m.address });
                }
            }
            if (!list.length && index.status === 'rejected') setApiError('We could not load the masjid directory right now. Please try again in a moment.');
            setMasjids(list);
            setIsLoading(false);
        });
        return () => { cancelled = true; };
    }, []);

    const regions = useMemo(() => {
        const seen = new Map();
        for (const m of masjids) if (m.c && m.r) seen.set(`${m.c}/${m.r}`, regionLabel(m.c, m.r));
        return [...seen.entries()].sort((a, b) => a[1].localeCompare(b[1]));
    }, [masjids]);

    const filtered = useMemo(() => {
        const term = searchTerm.trim().toLowerCase();
        let list = masjids.filter((m) => {
            if (filterOption === 'favorites' && !favorites.includes(favKey(m))) return false;
            if (filterOption === 'iqamah' && !m.v) return false;
            if (region !== 'all' && `${m.c}/${m.r}` !== region) return false;
            if (!term) return true;
            return [m.n, m.t, m.r && regionLabel(m.c, m.r), m.address].some((v) => v && v.toLowerCase().includes(term));
        });
        if (here) {
            list = list.map((m) => ({ ...m, mi: m.la != null ? distanceMi(here, m) : Infinity })).sort((a, b) => a.mi - b.mi);
        } else {
            list = [...list].sort((a, b) => (b.v ? 1 : 0) - (a.v ? 1 : 0) || a.n.localeCompare(b.n));
        }
        return list;
    }, [masjids, searchTerm, region, filterOption, favorites, here]);

    useEffect(() => { setCurrentPage(1); }, [searchTerm, region, filterOption, here]);

    const findNearMe = () => {
        if (!navigator.geolocation) { setLocationError('Your browser cannot share its location.'); return; }
        setLocating(true);
        setLocationError(null);
        navigator.geolocation.getCurrentPosition(
            (pos) => { setHere({ la: pos.coords.latitude, lo: pos.coords.longitude }); setRegion('all'); setLocating(false); },
            () => { setLocationError('Location is off. Allow it in your browser, or pick a state or province.'); setLocating(false); },
            { enableHighAccuracy: false, timeout: 10000, maximumAge: 300000 }
        );
    };

    const pageCount = Math.ceil(filtered.length / ITEMS_PER_PAGE);
    const current = filtered.slice((currentPage - 1) * ITEMS_PER_PAGE, currentPage * ITEMS_PER_PAGE);

    const handlePageChange = (event, value) => {
        setCurrentPage(value);
        window.scrollTo(0, 0);
    };

    return (
        <>
            <Box
                sx={{
                    background: `linear-gradient(135deg, ${theme.palette.primary.main}, ${theme.palette.primary.dark})`,
                    color: 'white',
                    pt: 8,
                    pb: 6,
                    position: 'relative'
                }}
            >
                <Container maxWidth="lg">
                    <Typography variant="h2" component="h1" gutterBottom fontWeight="500" sx={{ fontSize: { xs: '2.4rem', md: '3.75rem' } }}>
                        Mosque Directory
                    </Typography>
                    <Typography variant="h6" sx={{ maxWidth: 800, mb: 3, opacity: 0.9 }}>
                        {masjids.length ? `${masjids.length.toLocaleString('en-US')} masjids and musallas in the USA and Canada` : 'Masjids and musallas in the USA and Canada'}: directions, prayer times, Qibla, and iqamah times from the masjids on Masjid Connect.
                    </Typography>
                    <Breadcrumbs aria-label="breadcrumb" sx={{ color: 'rgba(255, 255, 255, 0.7)' }}>
                        <Link
                            component={RouterLink}
                            to="/"
                            sx={{ display: 'flex', alignItems: 'center', color: 'inherit', '&:hover': { color: 'white' } }}
                        >
                            <HomeIcon sx={{ mr: 0.5 }} fontSize="inherit" />
                            Home
                        </Link>
                        <Typography color="white" sx={{ display: 'flex', alignItems: 'center' }}>
                            <MosqueIcon sx={{ mr: 0.5 }} fontSize="inherit" />
                            Mosque Directory
                        </Typography>
                    </Breadcrumbs>
                </Container>

                <Box sx={{ position: 'absolute', bottom: -1, left: 0, width: '100%', lineHeight: 0, color: theme.palette.background.default }}>
                    <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1440 100">
                        <path
                            fill="currentColor"
                            fillOpacity="1"
                            d="M0,32L48,48C96,64,192,96,288,96C384,96,480,64,576,48C672,32,768,32,864,32C960,32,1056,32,1152,42.7C1248,53,1344,75,1392,85.3L1440,96L1440,320L1392,320C1344,320,1248,320,1152,320C1056,320,960,320,864,320C768,320,672,320,576,320C480,320,384,320,288,320C192,320,96,320,48,320L0,320Z"
                        />
                    </svg>
                </Box>
            </Box>

            <Container maxWidth="lg" sx={{ py: 6 }}>
                <Grid container spacing={4}>
                    <Grid item xs={12} md={3}>
                        <Paper elevation={2} sx={{ p: 3, mb: 3, borderRadius: 2 }}>
                            <Typography variant="h6" gutterBottom>Find a Masjid</Typography>

                            <Button
                                fullWidth
                                variant={here ? 'outlined' : 'contained'}
                                startIcon={locating ? <CircularProgress size={18} color="inherit" /> : <MyLocationIcon />}
                                onClick={here ? () => setHere(null) : findNearMe}
                                disabled={locating}
                                sx={{ mb: 1 }}
                            >
                                {here ? 'Sorted by distance · clear' : 'Near me'}
                            </Button>
                            {locationError && <Typography variant="caption" color="error">{locationError}</Typography>}

                            <TextField
                                fullWidth
                                variant="outlined"
                                label="Name, town or state"
                                value={searchTerm}
                                onChange={(e) => setSearchTerm(e.target.value)}
                                margin="normal"
                                InputProps={{ startAdornment: (<InputAdornment position="start"><SearchIcon /></InputAdornment>) }}
                            />

                            <FormControl fullWidth margin="normal">
                                <InputLabel>State / province</InputLabel>
                                <Select value={region} onChange={(e) => setRegion(e.target.value)} label="State / province">
                                    <MenuItem value="all">All</MenuItem>
                                    {regions.map(([k, label]) => <MenuItem key={k} value={k}>{label}</MenuItem>)}
                                </Select>
                            </FormControl>

                            <FormControl fullWidth margin="normal">
                                <InputLabel>Show</InputLabel>
                                <Select value={filterOption} onChange={(e) => setFilterOption(e.target.value)} label="Show">
                                    <MenuItem value="all">All masjids</MenuItem>
                                    <MenuItem value="iqamah">With iqamah times</MenuItem>
                                    <MenuItem value="favorites">My favorites</MenuItem>
                                </Select>
                            </FormControl>

                            <Typography variant="body2" sx={{ mt: 2 }}>
                                <Link href="/masjids/">Browse by state and province</Link>
                            </Typography>
                        </Paper>

                        <Box sx={{ textAlign: 'center', mt: 4, display: { xs: 'none', md: 'block' } }}>
                            <KaabaAnimation size={220} compact={true} />
                            <Typography variant="body2" sx={{ mt: 2, color: 'text.secondary', fontStyle: 'italic' }}>
                                "The mosques of Allah are only to be maintained by those who believe in Allah and the Last Day..."
                                <br /><span style={{ opacity: 0.8 }}>— Quran 9:18</span>
                            </Typography>
                        </Box>
                    </Grid>

                    <Grid item xs={12} md={9}>
                        {isLoading ? (
                            <Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center', py: 8 }}>
                                <CircularProgress size={48} />
                                <Typography sx={{ mt: 2 }}>Loading masjids...</Typography>
                            </Box>
                        ) : apiError ? (
                            <Paper sx={{ p: 4, textAlign: 'center' }}>
                                <Typography color="error" variant="h6">{apiError}</Typography>
                                <Button variant="contained" sx={{ mt: 2 }} onClick={() => window.location.reload()}>Try Again</Button>
                            </Paper>
                        ) : (
                            <>
                                <Typography variant="h5" sx={{ mb: 3 }}>
                                    {filtered.length.toLocaleString('en-US')} {filtered.length === 1 ? 'Masjid' : 'Masjids'}{here ? ', nearest first' : ''}
                                </Typography>

                                {here && filtered[0]?.mi > 150 && (
                                    <Alert severity="info" sx={{ mb: 3 }}>The directory covers the USA and Canada; the nearest masjid we list is {Math.round(filtered[0].mi)} miles away.</Alert>
                                )}

                                {filtered.length === 0 ? (
                                    <Paper sx={{ p: 4, textAlign: 'center' }}>
                                        <MosqueIcon sx={{ fontSize: 60, color: theme.palette.text.secondary, opacity: 0.5, mb: 2 }} />
                                        <Typography variant="h6" gutterBottom>No masjids found</Typography>
                                        <Typography variant="body2" color="textSecondary">
                                            {filterOption === 'favorites' ? 'You have no favorite masjids yet.' : 'Try a different name, town or state.'}
                                        </Typography>
                                        <Button variant="contained" sx={{ mt: 2 }} onClick={() => { setSearchTerm(''); setRegion('all'); setFilterOption('all'); }}>
                                            Show all masjids
                                        </Button>
                                    </Paper>
                                ) : (
                                    <Grid container spacing={3}>
                                        {current.map((m) => {
                                            const key = favKey(m);
                                            const where = [m.t, m.r && regionLabel(m.c, m.r)].filter(Boolean).join(', ') || m.address || '';
                                            const directions = m.la != null
                                                ? `https://www.google.com/maps/dir/?api=1&destination=${m.la},${m.lo}`
                                                : `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent([m.n, m.address || m.t].filter(Boolean).join(', '))}`;
                                            return (
                                                <Grid item xs={12} sm={6} lg={4} key={m.u}>
                                                    <Card sx={{ height: '100%', display: 'flex', flexDirection: 'column' }}>
                                                        <CardContent sx={{ flexGrow: 1 }}>
                                                            <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', gap: 1 }}>
                                                                <MasjidLink m={m} variant="h6" underline="hover" sx={{ mb: 1, lineHeight: 1.3 }}>{m.n}</MasjidLink>
                                                                <IconButton
                                                                    size="small"
                                                                    onClick={() => toggleFavorite(key)}
                                                                    aria-label={favorites.includes(key) ? 'Remove from favorites' : 'Add to favorites'}
                                                                >
                                                                    {favorites.includes(key) ? <FavoriteIcon sx={{ color: theme.palette.error.main }} /> : <FavoriteBorderIcon />}
                                                                </IconButton>
                                                            </Box>
                                                            {where && (
                                                                <Box sx={{ display: 'flex', alignItems: 'flex-start', mb: 1 }}>
                                                                    <LocationOnIcon fontSize="small" sx={{ color: theme.palette.text.secondary, mt: 0.3, mr: 1, flexShrink: 0 }} />
                                                                    <Typography variant="body2" color="text.secondary">
                                                                        {where}{here && Number.isFinite(m.mi) ? ` · ${m.mi < 10 ? m.mi.toFixed(1) : Math.round(m.mi)} mi` : ''}
                                                                    </Typography>
                                                                </Box>
                                                            )}
                                                            <Box sx={{ display: 'flex', gap: 0.5, flexWrap: 'wrap', mt: 1 }}>
                                                                {m.v && <Chip size="small" color="success" variant="outlined" icon={<VerifiedIcon fontSize="small" />} label="Iqamah times" />}
                                                                {m.k === 'musalla' && <Chip size="small" variant="outlined" label="Musalla" />}
                                                                {m.d && <Chip size="small" variant="outlined" label={m.d} />}
                                                            </Box>
                                                        </CardContent>
                                                        <Divider />
                                                        <CardActions sx={{ justifyContent: 'space-between' }}>
                                                            <Button size="small" startIcon={<DirectionsIcon />} component="a" href={directions} target="_blank" rel="noopener noreferrer">
                                                                Directions
                                                            </Button>
                                                            {m.u.startsWith('/mosque/')
                                                                ? <Button size="small" component={RouterLink} to={m.u}>Iqamah times</Button>
                                                                : <Button size="small" href={m.u}>Details</Button>}
                                                        </CardActions>
                                                    </Card>
                                                </Grid>
                                            );
                                        })}
                                    </Grid>
                                )}

                                {pageCount > 1 && (
                                    <Box sx={{ display: 'flex', justifyContent: 'center', mt: 4 }}>
                                        <Pagination count={pageCount} page={currentPage} onChange={handlePageChange} color="primary" siblingCount={0} />
                                    </Box>
                                )}

                                <AddMasjidCard />
                                <Typography variant="caption" color="text.secondary" sx={{ display: 'block', mt: 2 }}>
                                    Masjid data © <Link href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener noreferrer">OpenStreetMap contributors</Link> (ODbL) and the masjids on Masjid Connect.
                                </Typography>
                            </>
                        )}
                    </Grid>
                </Grid>
            </Container>
        </>
    );
};

export default MosqueDirectoryPage;
